namespace StickyNotes;
internal sealed record GoogleSession(string Subject,string Email,string RefreshToken);
internal sealed class GoogleDriveSync:IDisposable {
 internal const string Scope="https://www.googleapis.com/auth/drive.appdata";
 readonly HttpClient http;readonly string sessionPath;readonly string clientId;string? access;DateTimeOffset expiry;
 internal GoogleSession? Session {get;private set;}
 internal bool Configured=>clientId.EndsWith(".apps.googleusercontent.com",StringComparison.Ordinal);
 internal string AccountKey=>SyncJson.Hash(Encoding.UTF8.GetBytes(clientId+":"+Session!.Subject));
 internal GoogleDriveSync(string root,HttpMessageHandler? handler=null,string? clientIdOverride=null){http=handler==null?new HttpClient():new HttpClient(handler);http.Timeout=TimeSpan.FromSeconds(90);sessionPath=Path.Combine(root,".sync","google-session.dat");string config=Path.Combine(AppContext.BaseDirectory,"Assets","google-oauth.json");clientId=clientIdOverride??(File.Exists(config)?JsonDocument.Parse(File.ReadAllBytes(config)).RootElement.GetProperty("client_id").GetString()??"":"");if(File.Exists(sessionPath)){try{Session=JsonSerializer.Deserialize<GoogleSession>(ProtectedData.Unprotect(File.ReadAllBytes(sessionPath),null,DataProtectionScope.CurrentUser));}catch(CryptographicException){throw new InvalidDataException("A conexão Google deste Windows não pôde ser lida. Suas notas estão preservadas.");}}}
 static string Url64(byte[] bytes)=>Convert.ToBase64String(bytes).TrimEnd('=').Replace('+','-').Replace('/','_');
 internal async Task<GoogleSession> Authorize(CancellationToken token){if(!Configured)throw new InvalidOperationException("A conexão Google ainda precisa do cadastro OAuth do aplicativo. Nenhuma nota foi enviada.");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(token);timeout.CancelAfter(TimeSpan.FromMinutes(4));token=timeout.Token;string verifier=Url64(RandomNumberGenerator.GetBytes(48)),state=Url64(RandomNumberGenerator.GetBytes(32));var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{int port=((IPEndPoint)listener.LocalEndpoint).Port;string redirect=$"http://127.0.0.1:{port}/";var parameters=new Dictionary<string,string>{{"client_id",clientId},{"redirect_uri",redirect},{"response_type","code"},{"scope","openid email "+Scope},{"code_challenge",Url64(SHA256.HashData(Encoding.ASCII.GetBytes(verifier)))},{"code_challenge_method","S256"},{"state",state},{"access_type","offline"},{"prompt","consent select_account"}};string query=await new FormUrlEncodedContent(parameters).ReadAsStringAsync(token);Process.Start(new ProcessStartInfo("https://accounts.google.com/o/oauth2/v2/auth?"+query){UseShellExecute=true});string? code=null;while(code==null){using var socket=await listener.AcceptTcpClientAsync(token);using var stream=socket.GetStream();using var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);string? line=await reader.ReadLineAsync(token);if(line==null||line.Length>8192||!line.StartsWith("GET /?",StringComparison.Ordinal))continue;int headerBytes=line.Length;string? headerLine;while(!string.IsNullOrEmpty(headerLine=await reader.ReadLineAsync(token))){headerBytes+=headerLine.Length;if(headerBytes>16384)throw new InvalidDataException("Resposta de login inválida.");}var callback=new Uri("http://127.0.0.1"+line.Split(' ')[1]);var values=callback.Query.TrimStart('?').Split('&').Select(v=>v.Split('=',2)).Where(v=>v.Length==2).ToDictionary(v=>Uri.UnescapeDataString(v[0]),v=>Uri.UnescapeDataString(v[1].Replace('+',' ')));bool valid=values.GetValueOrDefault("state")==state;code=valid?values.GetValueOrDefault("code"):null;string html=GoogleLoginPage.Html(code!=null);byte[] body=Encoding.UTF8.GetBytes(html);byte[] header=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: no-store\r\nReferrer-Policy: no-referrer\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");await stream.WriteAsync(header,token);await stream.WriteAsync(body,token);if(valid&&values.ContainsKey("error"))throw new OperationCanceledException("Login Google cancelado.");}var result=await Token(new(){{"client_id",clientId},{"code",code},{"code_verifier",verifier},{"redirect_uri",redirect},{"grant_type","authorization_code"}},token);string granted=result.GetProperty("scope").GetString()??"";if(!granted.Split(' ').Contains(Scope))throw new InvalidOperationException("Autorize apenas a pasta privada do Sticky Notes para sincronizar.");string grantedAccess=result.GetProperty("access_token").GetString()!;using var request=new HttpRequestMessage(HttpMethod.Get,"https://openidconnect.googleapis.com/v1/userinfo");request.Headers.Authorization=new("Bearer",grantedAccess);using var response=await http.SendAsync(request,token);if(!response.IsSuccessStatusCode)throw new InvalidOperationException("Não foi possível confirmar a conta Google.");using var info=JsonDocument.Parse(await response.Content.ReadAsByteArrayAsync(token));if(!info.RootElement.GetProperty("email_verified").GetBoolean())throw new InvalidOperationException("Confirme seu e-mail Google antes de sincronizar.");return new(info.RootElement.GetProperty("sub").GetString()!,info.RootElement.GetProperty("email").GetString()!,result.GetProperty("refresh_token").GetString()!);}finally{listener.Stop();}}
 internal void Accept(GoogleSession session){Directory.CreateDirectory(Path.GetDirectoryName(sessionPath)!);Store.Atomic(sessionPath,ProtectedData.Protect(SyncJson.Bytes(session),null,DataProtectionScope.CurrentUser));Session=session;access=null;expiry=default;}
 internal void Disconnect(){Session=null;access=null;if(File.Exists(sessionPath))File.Delete(sessionPath);if(File.Exists(sessionPath+".bak"))File.Delete(sessionPath+".bak");}
 async Task<JsonElement> Token(Dictionary<string,string> form,CancellationToken token){if(GoogleDesktopClient.Registration.Length>0)form["client_secret"]=GoogleDesktopClient.Registration;using var response=await http.PostAsync("https://oauth2.googleapis.com/token",new FormUrlEncodedContent(form),token);if(!response.IsSuccessStatusCode){string reason="Google indisponível. Suas notas estão salvas neste computador.";try{using var error=JsonDocument.Parse(await response.Content.ReadAsByteArrayAsync(token));string code=error.RootElement.GetProperty("error").GetString()??"";if(new[]{"invalid_client","invalid_request","invalid_grant","invalid_scope","unauthorized_client","access_denied"}.Contains(code))reason="Google recusou o login ("+code+"). Suas notas locais foram preservadas.";if(error.RootElement.TryGetProperty("error_description",out var description)&&(description.GetString()??"").Contains("client_secret",StringComparison.OrdinalIgnoreCase))reason="O cadastro Google exige autenticação adicional do cliente. Nenhuma nota foi enviada.";}catch(JsonException){}throw new InvalidOperationException(reason);}using var json=JsonDocument.Parse(await response.Content.ReadAsByteArrayAsync(token));return json.RootElement.Clone();}
 async Task<string> Access(CancellationToken token){if(Session==null)throw new InvalidOperationException("Conecte uma conta Google.");if(access!=null&&DateTimeOffset.UtcNow<expiry)return access;var result=await Token(new(){{"client_id",clientId},{"refresh_token",Session.RefreshToken},{"grant_type","refresh_token"}},token);if(result.TryGetProperty("refresh_token",out var refresh))Accept(Session with{RefreshToken=refresh.GetString()!});access=result.GetProperty("access_token").GetString()!;expiry=DateTimeOffset.UtcNow.AddSeconds(result.GetProperty("expires_in").GetInt32()-60);return access;}
 async Task<byte[]> Send(HttpRequestMessage request,CancellationToken token,int max=48*1024*1024){request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",await Access(token));using var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token);if(!response.IsSuccessStatusCode)throw new InvalidOperationException(response.StatusCode==HttpStatusCode.Unauthorized?"Reconecte a conta Google para continuar.":"Não foi possível sincronizar com o Google Drive ("+(int)response.StatusCode+"). As notas locais foram preservadas.");if(response.Content.Headers.ContentLength>max)throw new InvalidDataException("Resposta Google extensa demais.");using var stream=await response.Content.ReadAsStreamAsync(token);using var output=new MemoryStream();byte[] buffer=new byte[65536];int count;while((count=await stream.ReadAsync(buffer,token))>0){if(output.Length+count>max)throw new InvalidDataException("Resposta Google extensa demais.");output.Write(buffer,0,count);}return output.ToArray();}
 internal async Task<Dictionary<string,string>> List(CancellationToken token){var files=new Dictionary<string,string>();string? page=null;do{string url="https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&pageSize=1000&fields=nextPageToken,files(id,name)&q="+Uri.EscapeDataString("trashed = false and name contains 'sticky-v1-'")+(page==null?"":"&pageToken="+Uri.EscapeDataString(page));using var request=new HttpRequestMessage(HttpMethod.Get,url);using var doc=JsonDocument.Parse(await Send(request,token,4*1024*1024));foreach(var file in doc.RootElement.GetProperty("files").EnumerateArray()){string name=file.GetProperty("name").GetString()!;if(name.StartsWith("sticky-v1-")&&name.EndsWith(".json")){string hash=name[10..^5];if(SyncJson.Id(hash,64))files[hash]=file.GetProperty("id").GetString()!;}}page=doc.RootElement.TryGetProperty("nextPageToken",out var next)?next.GetString():null;if(files.Count>50000)throw new InvalidDataException("Histórico extenso demais. As notas locais foram preservadas.");}while(page!=null);return files;}
 internal async Task<SyncRevision> Download(string file,string hash,CancellationToken token){using var request=new HttpRequestMessage(HttpMethod.Get,"https://www.googleapis.com/drive/v3/files/"+Uri.EscapeDataString(file)+"?alt=media");return SyncJson.Read(await Send(request,token),hash);}
 internal async Task Upload(string hash,SyncRevision revision,CancellationToken token){byte[] bytes=SyncJson.Bytes(revision);if(bytes.Length>48*1024*1024)throw new InvalidDataException("Uma nota excede 48 MB. Reduza as imagens para sincronizá-la.");using var multipart=new MultipartContent("related");var metadata=new ByteArrayContent(SyncJson.Bytes(new{name="sticky-v1-"+hash+".json",parents=new[]{"appDataFolder"}}));metadata.Headers.ContentType=new("application/json");multipart.Add(metadata);var data=new ByteArrayContent(bytes);data.Headers.ContentType=new("application/json");multipart.Add(data);using var request=new HttpRequestMessage(HttpMethod.Post,"https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id"){Content=multipart};await Send(request,token,1024*1024);}
 public void Dispose()=>http.Dispose();
}
